@media (min-width: 1200px){
.navbar_nav .menu-item .sub-menu li a.nav_link.menu_img_style_two .img-link { 
    overflow: hidden;
height: 300px;
		width:100%;
	padding:10px;
}
	.navbar_nav .menu-item .sub-menu li a.nav_link.menu_img_style_two .img-link img{
		box-shadow:0px 5px 22px 0px rgba(0,0,0,0.05);
		 border-radius:10px;

	}

}

.navbar_nav .menu-item-1588.flex_menu_activate:not(.menu_default) .sub-menu>li{
	padding:15px 0px 5px!important;
}

.volunteer-style_1 .image-box .img_link img{
	object-position:top;
}
@media (max-width: 992px){
.slider_box_V1 .smtitle, .slider_box_V2 .smtitle, .slider_box_V3 .smtitle, .slider_box_V4 .smtitle{
	display:none!important;
} 
}
.slideralignment_center .button_group{
	justify-content:center!important;
	align-items:center!important;
}

.elementor-1627 .elementor-element.elementor-element-bfbadcd .header .logo_box img {
    width: 200px !important;
}
.logo_box .logo img {
    width: 180px;
}
.logo_box .logo img {
    width: 180px !important;
}
    .page_header_default {
        background: 0 0;
			padding:0px;
    }
input[type=checkbox] {
    margin: 0 3px 0 0;
    position: relative;
    width: auto;
    border: 1px solid black !important;
}
input[type=radio] {
    display: inline;
    margin: 0 .25em 0 0;
    outline: none;
    width: auto;
    border: 1px solid black !important;
}

/* Reparatii: buton video fara film */
.elementor-element-a3da994 .video_box_null { display: none; }

/* Reparatii: elemente care par butoane, dar n-au unde duce */
/* Sablonul le inveleste automat in <a href="#">, iar widgetul nu are camp de adresa.
   Daca li se pune candva o adresa reala, href nu mai e "#" si regula nu se mai aplica. */
.elementor-widget-risehand-client-carousel-v1 a[href="#"],
.elementor-widget-risehand-icon-box a[href="#"],
.elementor-widget-risehand-list-v1 a[href="#"] {
	pointer-events: none;
	cursor: default;
}

